"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { reveal, revealDelay } from "@/lib/motion";
import styles from "./bookshelf.module.css";

const TRANSITION = { duration: 0.38, ease: [0.22, 1, 0.36, 1] as const };
const LIFT_TRANSITION = {
  type: "spring",
  stiffness: 340,
  damping: 25,
  mass: 0.7,
} as const;

export interface BookshelfBook {
  id: string;
  title: string;
  author: string;
  cover: { src: string; width: number; height: number; alt: string };
  spine: { src: string; height: number; width: number };
}

export interface BookshelfProps {
  /** Books render in the supplied order. IDs must be unique and stable. */
  books: readonly BookshelfBook[];
  /** Initially open book. Missing or unknown IDs start with every book closed. */
  defaultBookId?: string | null;
  label?: string;
  emptyMessage?: string;
  coverUnavailableMessage?: string;
  /** Closed-book hover lift in pixels, clamped to 0 through 20. */
  liftAmount?: number;
  /** Optional once-only entrance for shelves below the fold. */
  revealOnScroll?: boolean;
  className?: string;
}

function BookCover({
  book,
  unavailableMessage,
}: {
  book: BookshelfBook;
  unavailableMessage: string;
}) {
  const [failed, setFailed] = useState(false);

  return (
    <span className={styles.cover}>
      {failed ? (
        <span className={styles.fallback}>
          <span>{book.title}</span>
          <span>{book.author}</span>
          <span>{unavailableMessage}</span>
        </span>
      ) : (
        // Consumer artwork needs no Next.js loader or domain configuration.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={book.cover.src}
          width={book.cover.width}
          height={book.cover.height}
          alt={book.cover.alt}
          loading="eager"
          decoding="sync"
          className={styles.coverImage}
          onError={() => setFailed(true)}
        />
      )}
    </span>
  );
}

export function Bookshelf({
  books,
  defaultBookId = null,
  label = "Bookshelf",
  emptyMessage = "More books will find their way here.",
  coverUnavailableMessage = "Cover unavailable",
  liftAmount = 10,
  revealOnScroll = false,
  className,
}: BookshelfProps) {
  const [selectedId, setSelectedId] = useState<string | null>(() =>
    books.some((book) => book.id === defaultBookId) ? defaultBookId : null,
  );
  const activeId = books.some((book) => book.id === selectedId)
    ? selectedId
    : null;
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const root = useRef<HTMLDivElement>(null);
  const rail = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const instant = reduceMotion !== false;
  const transition = instant ? { duration: 0 } : TRANSITION;
  const lift = Number.isFinite(liftAmount)
    ? Math.min(20, Math.max(0, liftAmount))
    : 10;

  useEffect(() => {
    function dismissOutside(event: PointerEvent) {
      const target = event.target;
      if (
        target instanceof Element &&
        root.current?.contains(target) &&
        target.closest("[data-bookshelf-book]")
      ) {
        return;
      }
      // The header floats over the page; pressing its controls (theme,
      // search, GitHub, menu) must not close an open book.
      if (target instanceof Element && target.closest("header")) {
        return;
      }
      setSelectedId(null);
    }

    function dismissOnEscape(event: KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedId(null);
      setHoveredId(null);
    }

    document.addEventListener("pointerdown", dismissOutside);
    document.addEventListener("keydown", dismissOnEscape);
    return () => {
      document.removeEventListener("pointerdown", dismissOutside);
      document.removeEventListener("keydown", dismissOnEscape);
    };
  }, []);

  useEffect(() => {
    if (!activeId) return;
    const book = root.current?.querySelector<HTMLElement>(
      `[data-bookshelf-book="${CSS.escape(activeId)}"]`,
    );
    const position = book?.parentElement;
    const railElement = rail.current;
    if (!position || !railElement) return;
    const max = railElement.scrollWidth - railElement.clientWidth;
    const centered =
      position.offsetLeft -
      (railElement.clientWidth - position.offsetWidth) / 2;
    const next = Math.max(0, Math.min(max, centered));
    if (Math.abs(next - railElement.scrollLeft) > 1) {
      railElement.scrollLeft = next;
    }
  }, [activeId, books]);

  if (books.length === 0) {
    return (
      <div
        role="group"
        aria-label={label}
        className={cn(styles.shelf, className)}
      >
        <p className="px-6 py-16 text-sm text-muted-foreground">
          {emptyMessage}
        </p>
      </div>
    );
  }

  return (
    <div
      ref={root}
      role="group"
      aria-label={label}
      className={cn(styles.shelf, className)}
    >
      <noscript>
        <style>{`.${styles.reveal} { opacity: 1 !important; transform: none !important; }`}</style>
      </noscript>
      <div ref={rail} className={styles.rail}>
        <div className={styles.books}>
          {books.map((book, index) => {
            const active = activeId === book.id;
            const bookStyle = {
              "--book-height": `${book.spine.height}px`,
              "--spine-width": `${book.spine.width}px`,
              "--cover-ratio": book.cover.width / book.cover.height,
            } as CSSProperties;

            return (
              <motion.div
                key={book.id}
                className={styles.reveal}
                {...(revealOnScroll && !reduceMotion
                  ? reveal({
                      y: 28,
                      delay: revealDelay(index, 0.06, 0.36),
                      margin: "0px 0px -120px 0px",
                      amount: 0.3,
                    })
                  : { initial: false })}
              >
                <motion.button
                  type="button"
                  layout="position"
                  transition={transition}
                  data-bookshelf-book={book.id}
                  data-open={active}
                  className={styles.book}
                  style={bookStyle}
                  aria-label={`${book.title}, by ${book.author}`}
                  aria-pressed={active}
                  onPointerEnter={(event) => {
                    if (
                      event.pointerType === "mouse" &&
                      window.matchMedia("(hover: hover) and (pointer: fine)")
                        .matches
                    ) {
                      setHoveredId(book.id);
                    }
                  }}
                  onPointerLeave={() => setHoveredId(null)}
                  onClick={() =>
                    setSelectedId((current) =>
                      current === book.id ? null : book.id,
                    )
                  }
                >
                  <motion.span
                    className={styles.artwork}
                    initial={false}
                    animate={{
                      y:
                        !instant && !active && hoveredId === book.id
                          ? -lift
                          : 0,
                    }}
                    transition={
                      instant
                        ? { duration: 0 }
                        : active
                          ? TRANSITION
                          : LIFT_TRANSITION
                    }
                  >
                    <motion.span
                      className={styles.volume}
                      initial={false}
                      animate={{ opacity: active ? 1 : 0 }}
                      transition={{ duration: instant ? 0 : 0.18 }}
                      aria-hidden="true"
                    >
                      <BookCover
                        key={book.cover.src}
                        book={book}
                        unavailableMessage={coverUnavailableMessage}
                      />
                    </motion.span>
                    <motion.span
                      className={styles.spine}
                      initial={false}
                      animate={{ opacity: active ? 0 : 1 }}
                      transition={{ duration: instant ? 0 : 0.18 }}
                      aria-hidden="true"
                    >
                      {/* Artwork uses the supplied URL without a framework image loader. */}
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img
                        src={book.spine.src}
                        alt=""
                        width={book.spine.width}
                        height={book.spine.height}
                        loading="eager"
                        className={styles.spineImage}
                      />
                    </motion.span>
                  </motion.span>
                </motion.button>
              </motion.div>
            );
          })}
        </div>
      </div>
      <div className={styles.baseline} aria-hidden="true" />
    </div>
  );
}

.shelf {
  --book-scale: 1;
  margin: 0 auto;
  padding: 8px 0 24px;
}

.rail {
  position: relative;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  /* A cover opening changes the row width, so the bar would flicker for the
     length of the animation. The shelf still scrolls by wheel, trackpad, touch,
     and keyboard focus. */
  scrollbar-width: none;
}

.rail::-webkit-scrollbar {
  display: none;
}

.books {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  width: max-content;
  min-height: calc(320px * var(--book-scale));
  margin: 0 auto;
  padding: 24px 32px 0;
}

.book {
  --depth: calc(var(--spine-width) * var(--book-scale));
  position: relative;
  display: block;
  flex: 0 0 auto;
  width: calc(var(--depth) + 4px);
  height: calc(var(--book-height) * var(--book-scale));
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition-property: none;
  outline: none;
}

.reveal {
  flex: 0 0 auto;
}

.book[data-open="true"] {
  width: calc(
    var(--book-height) * var(--book-scale) * var(--cover-ratio) + 5px
  );
  z-index: 1;
}

.book:focus-visible {
  outline: 2px solid var(--ring, currentColor);
  outline-offset: 5px;
  border-radius: var(--radius-sm, 0.25rem);
}

.artwork {
  position: absolute;
  inset: 0;
  display: block;
  overflow: clip;
  pointer-events: none;
}

.volume {
  position: absolute;
  inset: 0 auto 0 2px;
  display: block;
  width: calc(var(--book-height) * var(--book-scale) * var(--cover-ratio));
  pointer-events: none;
}

.cover,
.spine {
  position: absolute;
  display: block;
}

.cover {
  inset: 0;
  overflow: hidden;
  background: var(--card, #fafafa);
  border-radius: 0 calc(var(--radius-sm, 0.25rem) / 2)
    calc(var(--radius-sm, 0.25rem) / 2) 0;
}

.coverImage,
.spineImage {
  display: block;
  width: 100%;
  height: 100%;
}

.coverImage {
  object-fit: cover;
}

.spine {
  inset: 0 auto 0 2px;
  width: var(--depth);
  overflow: hidden;
  border-radius: calc(var(--radius-sm, 0.25rem) / 2);
  pointer-events: none;
}

.cover::after,
.spine::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px var(--border, #d4d4d4);
  pointer-events: none;
}

.baseline {
  margin: 0 24px;
  height: 8px;
  border-radius: var(--radius-lg, 0.5rem);
  background: var(--border, #d4d4d4);
}

.fallback {
  display: flex;
  height: 100%;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  padding: 10px;
  background: var(--secondary, #f5f5f5);
  color: var(--secondary-foreground, #171717);
  font-size: 12px;
  line-height: 1.4;
  text-align: center;
}

.fallback span:last-child {
  color: var(--muted-foreground, #737373);
  font-size: 10px;
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1 !important;
    transform: none !important;
  }
}

@media (prefers-reduced-motion: reduce), (hover: none), (pointer: coarse) {
  .artwork {
    transform: none !important;
  }
}

@media (width < 480px) {
  .shelf {
    --book-scale: 0.78;
    padding-top: 28px;
  }

  .books {
    gap: 2px;
    padding-inline: 24px;
  }

  .baseline {
    margin-inline: 0;
    border-radius: var(--radius, 0.45rem);
  }
}

import type { MotionProps, Transition, Variants } from "motion/react";

/**
 * Shared entrance motion for the site.
 *
 * The hero greeting sets the reference: a short fade with a small rise.
 * Everything that enters on scroll speaks the same language so the page reads
 * as one system rather than a dozen separate reveals.
 *
 * Timing is deliberately split per value, which is what makes it feel snappy
 * rather than slow:
 *   - opacity lands first (fast), so nothing lingers as a ghost
 *   - y settles on a critically damped spring, so it stops without wobble
 *
 * Only `opacity` and `y` are animated. Filter-based reveals were removed:
 * animating `filter: blur()` cannot be composited and forces the browser to
 * re-rasterize the whole subtree on every frame, which shows up as forced
 * reflow and scroll jank on section-sized content.
 *
 * Reduced motion: site-internal usage relies on the `[data-reveal]` rule in
 * `app/globals.css`, which pins the resolved state with `!important` and so
 * beats Motion's inline styles. That keeps these helpers hook-free and avoids
 * hydration mismatches. Registry components cannot depend on this file or that
 * stylesheet, so they gate on `useReducedMotion()` locally instead.
 */

export const MOTION_EASE = [0.22, 1, 0.36, 1] as const;

/** Damping ratio is ~1.03, so `y` never overshoots into a bounce. */
const REVEAL_SPRING = {
  type: "spring",
  stiffness: 420,
  damping: 34,
  mass: 0.7,
} satisfies Transition;

const OPACITY_DURATION = 0.18;

export type RevealOptions = {
  /** Rise distance in px. Keep it small: this is a settle, not a slide. */
  y?: number;
  /** Seconds to hold before starting. Use `revealDelay()` for lists. */
  delay?: number;
  /** Intersection root margin for scroll-triggered reveals. */
  margin?: string;
  /** How much of the element must be visible before it fires. */
  amount?: "some" | "all" | number;
};

type RevealProps = Pick<
  MotionProps,
  "initial" | "animate" | "whileInView" | "viewport" | "transition"
> & {
  "data-reveal": "";
};

function hiddenState(y: number) {
  return { opacity: 0, y };
}

function resolvedState() {
  return { opacity: 1, y: 0 };
}

function revealTransition(delay: number): Transition {
  return {
    default: { ...REVEAL_SPRING, delay },
    opacity: { duration: OPACITY_DURATION, ease: MOTION_EASE, delay },
  };
}

/**
 * Scroll-triggered fade + rise. Fires once.
 *
 * Put the reveal on whatever the eye actually reads: text, rows, cards. When a
 * section animates its own children, let the section wrapper rise without its
 * own delay so entrances never stack.
 */
export function reveal({
  y = 8,
  delay = 0,
  margin = "-40px",
  amount,
}: RevealOptions = {}): RevealProps {
  return {
    "data-reveal": "",
    initial: hiddenState(y),
    whileInView: resolvedState(),
    viewport: { once: true, margin, amount },
    transition: revealTransition(delay),
  };
}

/**
 * Same reveal, driven by mount instead of scroll. For content that appears in
 * response to an interaction, such as rows inside a section that just expanded.
 */
export function revealOnMount({
  y = 8,
  delay = 0,
}: Omit<RevealOptions, "margin" | "amount"> = {}): RevealProps {
  return {
    "data-reveal": "",
    initial: hiddenState(y),
    animate: resolvedState(),
    transition: revealTransition(delay),
  };
}

/**
 * Variant pair for parent-driven staggers, where the container owns the
 * sequencing via `staggerChildren`.
 */
export function revealVariants({
  y = 8,
}: Pick<RevealOptions, "y"> = {}): Variants {
  return {
    hidden: hiddenState(y),
    visible: {
      ...resolvedState(),
      transition: revealTransition(0),
    },
  };
}

/**
 * Capped stagger for lists. The cap matters: without it a long list leaves the
 * last item waiting a second to appear, which reads as sluggish.
 */
export function revealDelay(index: number, step = 0.04, max = 0.2) {
  return Math.min(index * step, max);
}
